    }
    // Assign
    Map<String, Map<String, Set<String>>> expectedFaultZoneMap = Collections.singletonMap(_testFaultZoneId, assignmentSet.stream().collect(Collectors.groupingBy(AssignableReplica::getResourceName, Collectors.mapping(AssignableReplica::getPartitionName, Collectors.toSet()))));
    assignmentSet.stream().forEach(replica -> context.addPartitionToFaultZone(_testFaultZoneId, replica.getResourceName(), replica.getPartitionName()));
