@Test
public void testNormalUsage() throws IOException {
    // Test 1 - initialize the cluster model based on the data cache.
    ResourceControllerDataProvider testCache = setupClusterDataCache();
    Set<AssignableReplica> assignableReplicas = generateReplicas(testCache);
    Set<AssignableNode> assignableNodes = generateNodes(testCache);
    ClusterContext context = new ClusterContext(assignableReplicas, assignableNodes, Collections.emptyMap(), Collections.emptyMap());
    ClusterModel clusterModel = new ClusterModel(context, assignableReplicas, assignableNodes);
    Assert.assertTrue(clusterModel.getContext().getAssignmentForFaultZoneMap().values().stream().allMatch(resourceMap -> resourceMap.values().isEmpty()));
    Assert.assertFalse(clusterModel.getAssignableNodes().values().stream().anyMatch(node -> node.getAssignedReplicaCount() != 0));
    // The initialization of the context, node and replication has been tested separately. So for
    // cluster model, focus on testing the assignment and release.
    // Assign
    AssignableReplica replica = assignableReplicas.iterator().next();
    AssignableNode assignableNode = assignableNodes.iterator().next();
    clusterModel.assign(replica.getResourceName(), replica.getPartitionName(), replica.getReplicaState(), assignableNode.getInstanceName());
    Assert.assertTrue(clusterModel.getContext().getAssignmentForFaultZoneMap().get(assignableNode.getFaultZone()).get(replica.getResourceName()).contains(replica.getPartitionName()));
    Assert.assertTrue(assignableNode.getAssignedPartitionsMap().get(replica.getResourceName()).contains(replica.getPartitionName()));
    // Assign a nonexist replication
    try {
        clusterModel.assign("NOT-EXIST", replica.getPartitionName(), replica.getReplicaState(), assignableNode.getInstanceName());
        Assert.fail("Assigning a non existing resource partition shall fail.");
    } catch (HelixException ex) {
        // expected
    }
    // Assign a non-exist replication
    try {
        clusterModel.assign(replica.getResourceName(), replica.getPartitionName(), replica.getReplicaState(), "NON-EXIST");
        Assert.fail("Assigning a resource partition to a non existing instance shall fail.");
    } catch (HelixException ex) {
        // expected
    }
    // Release
    clusterModel.release(replica.getResourceName(), replica.getPartitionName(), replica.getReplicaState(), assignableNode.getInstanceName());
    Assert.assertTrue(clusterModel.getContext().getAssignmentForFaultZoneMap().values().stream().allMatch(resourceMap -> resourceMap.values().stream().allMatch(partitions -> partitions.isEmpty())));
    Assert.assertFalse(clusterModel.getAssignableNodes().values().stream().anyMatch(node -> node.getAssignedReplicaCount() != 0));
}

