    INSTANCE_0, // No change
    "MASTER", // OFFLINE -> DROPPED (downward)
    INSTANCE_1, // OFFLINE -> DROPPED (downward)
    "DROPPED", // OFFLINE -> SLAVE (upward)
    INSTANCE_2, // OFFLINE -> SLAVE (upward)
    "SLAVE");
    List<Message> messages = processAndGetMessages(stateModelDef, currentStates, bestPossible, 3);
    // Verify: 2 messages, upward gets active count, DROPPED doesn't
    Assert.assertEquals(messages.size(), 2);
    Message upwardMsg = messages.stream().filter(m -> m.getTgtName().equals(INSTANCE_2) && m.getToState().equals("SLAVE")).findFirst().orElse(null);
    Message droppedMsg = messages.stream().filter(m -> m.getTgtName().equals(INSTANCE_1) && m.getToState().equals("DROPPED")).findFirst().orElse(null);
    Assert.assertNotNull(upwardMsg, "Should have upward transition message");
    Assert.assertNotNull(droppedMsg, "Should have dropped transition message");
    Assert.assertEquals(upwardMsg.getCurrentActiveReplicaNumber(), 1, "Upward transition should have current active replica count");
    Assert.assertEquals(droppedMsg.getCurrentActiveReplicaNumber(), -1, "DROPPED transition should not have currentActiveReplicaNumber");
}

