    // Check failed continuous task rebalance counter is not updated
    result = TestHelper.verify(() -> {
        try {
            Long value = (Long) _server.getAttribute(getMbeanName(CLUSTER_NAME), "ContinuousTaskRebalanceFailureCount");
            return value != null && (value == 0);
        } catch (Exception e) {
            return false;
        }
    }, TIMEOUT);
    Assert.assertTrue(result);
    // Check if failed continuous resource rebalance counter is updated
    result = TestHelper.verify(() -> {
        try {
            Long value = (Long) _server.getAttribute(getMbeanName(CLUSTER_NAME), "ContinuousResourceRebalanceFailureCount");
            return value != null && (value > 0);
        } catch (Exception e) {
            return false;
        }
    }, TIMEOUT);
    Assert.assertTrue(result);
}

