    ClusterControllerManager firstController = new ClusterControllerManager(ZK_ADDR, CLUSTER_NAME, "FirstController");
    firstController.syncStart();
    verifyControllerIsLeader(firstController);
    ClusterControllerManager secondController = new ClusterControllerManager(ZK_ADDR, CLUSTER_NAME, "SecondController");
