@Test
public void testMissingTopStateDurationMonitoring() throws Exception {
    String clusterName = "testCluster-TestControllerLeadershipChange";
    String instanceName = clusterName + "-participant";
    String resourceName = "testResource";
    int numPartition = 1;
    int numReplica = 1;
    int simulatedTransitionDelayMs = 100;
    String stateModel = "LeaderStandby";
    ObjectName resourceMBeanObjectName = getResourceMonitorObjectName(clusterName, resourceName);
    MBeanServer beanServer = ManagementFactory.getPlatformMBeanServer();
    // Create cluster
    _gSetupTool.addCluster(clusterName, true);
    // Create cluster verifier
    ZkHelixClusterVerifier clusterVerifier = new BestPossibleExternalViewVerifier.Builder(clusterName).setZkClient(_gZkClient).setWaitTillVerify(TestHelper.DEFAULT_REBALANCE_PROCESSING_WAIT_TIME).build();
    // Create participant
    _gSetupTool.addInstanceToCluster(clusterName, instanceName);
    MockParticipantManager participant = new MockParticipantManager(ZK_ADDR, clusterName, instanceName, simulatedTransitionDelayMs);
    participant.syncStart();
    // Create controller, since this is the only controller, it will be the leader
    HelixManager manager1 = HelixManagerFactory.getZKHelixManager(clusterName, clusterName + "-manager1", InstanceType.CONTROLLER, ZK_ADDR);
    manager1.connect();
    Assert.assertTrue(manager1.isLeader());
    // Create resource
    _gSetupTool.addResourceToCluster(clusterName, resourceName, numPartition, stateModel, IdealState.RebalanceMode.SEMI_AUTO.name());
    // Rebalance Resource
    _gSetupTool.rebalanceResource(clusterName, resourceName, numReplica);
    // Wait for rebalance
    Assert.assertTrue(clusterVerifier.verifyByPolling());
    // Trigger missing top state in manager1
    participant.syncStop();
    Thread.sleep(1000);
    // Starting manager2
    HelixManager manager2 = HelixManagerFactory.getZKHelixManager(clusterName, clusterName + "-manager2", InstanceType.CONTROLLER, ZK_ADDR);
    manager2.connect();
    // Set leader to manager2
    setLeader(manager2);
    Assert.assertFalse(manager1.isLeader());
    Assert.assertTrue(manager2.isLeader());
    // Wait for rebalance
    Assert.assertTrue(clusterVerifier.verify());
    Thread.sleep(1000);
    // The moment before manager1 regain leadership. The topstateless duration will start counting.
    long start = System.currentTimeMillis();
    setLeader(manager1);
    Assert.assertTrue(manager1.isLeader());
    Assert.assertFalse(manager2.isLeader());
    // Make resource top state to come back by restarting participant
    participant = new MockParticipantManager(ZK_ADDR, clusterName, instanceName);
    participant.syncStart();
    _gSetupTool.rebalanceResource(clusterName, resourceName, numReplica);
    Assert.assertTrue(clusterVerifier.verifyByPolling());
    // The moment that partition top state has been recovered. The topstateless duration stopped counting.
    long end = System.currentTimeMillis();
    // Resource lost top state, and manager1 lost leadership for 2000ms, because manager1 will
    // clean monitoring cache after re-gaining leadership, so max value of hand off duration should
    // not have such a large value
    long duration = (long) beanServer.getAttribute(resourceMBeanObjectName, "PartitionTopStateHandoffDurationGauge.Max");
    long controllerOpDuration = end - start;
    Assert.assertTrue(duration >= simulatedTransitionDelayMs && duration <= controllerOpDuration, String.format("The recorded TopState-less duration is %d. But the controller operation duration is %d.", duration, controllerOpDuration));
    participant.syncStop();
    manager1.disconnect();
    manager2.disconnect();
    deleteCluster(clusterName);
}

@Test
public void test() throws Exception {
    String className = TestHelper.getTestClassName();
    String methodName = TestHelper.getTestMethodName();
    String clusterName = className + "_" + methodName;
    int n = 12;
    final int p = 256;
    BaseDataAccessor<ZNRecord> baseAccessor = new ZkBaseDataAccessor<ZNRecord>(_gZkClient);
    final HelixDataAccessor accessor = new ZKHelixDataAccessor(clusterName, baseAccessor);
    final PropertyKey.Builder keyBuilder = accessor.keyBuilder();
    System.out.println("START " + clusterName + " at " + new Date(System.currentTimeMillis()));
    // participant port
    TestHelper.// participant port
    setupCluster(// participant port
    clusterName, // participant port
    ZK_ADDR, // participant port
    12918, // participant name prefix
    "localhost", // resource name prefix
    "TestDB", // resources
    1, // partitions per resource
    p, // number of nodes
    n, // replicas
    1, "LeaderStandby", RebalanceMode.FULL_AUTO, // do rebalance
    true);
    enablePersistBestPossibleAssignment(_gZkClient, clusterName, true);
    // start participants
    Random random = new Random();
    MockParticipantManager[] participants = new MockParticipantManager[n];
    for (int i = 0; i < n; i++) {
        String instanceName = "localhost_" + (12918 + i);
        participants[i] = new MockParticipantManager(ZK_ADDR, clusterName, instanceName);
        participants[i].syncStart();
        Thread.sleep(Math.abs(random.nextInt()) % 500 + 500);
    }
    ClusterControllerManager controller = new ClusterControllerManager(ZK_ADDR, clusterName, "controller_0");
    controller.syncStart();
    BestPossibleExternalViewVerifier verifier = new BestPossibleExternalViewVerifier.Builder(clusterName).setZkClient(_gZkClient).setWaitTillVerify(TestHelper.DEFAULT_REBALANCE_PROCESSING_WAIT_TIME).build();
    boolean result = verifier.verifyByPolling();
    Assert.assertTrue(result);
    // make sure all partitions are assigned and no partitions is assigned to STANDBY state
    result = TestHelper.verify(new TestHelper.Verifier() {

        @Override
        public boolean verify() throws Exception {
            ExternalView extView = accessor.getProperty(keyBuilder.externalView("TestDB0"));
            for (int i = 0; i < p; i++) {
                String partition = "TestDB0_" + i;
                Map<String, String> map = extView.getRecord().getMapField(partition);
                if (map == null || map.size() != 1) {
                    return false;
                }
            }
            return true;
        }
    }, 10 * 1000);
    if (!result) {
        ExternalView extView = accessor.getProperty(keyBuilder.externalView("TestDB0"));
        for (int i = 0; i < p; i++) {
            String partition = "TestDB0_" + i;
            Map<String, String> map = extView.getRecord().getMapField(partition);
            if (map == null || map.size() != 1) {
                LOG.error(partition + ": " + map);
            }
        }
    }
    Assert.assertTrue(result);
    // clean up
    controller.syncStop();
    for (int i = 0; i < n; i++) {
        participants[i].syncStop();
    }
    TestHelper.dropCluster(clusterName, _gZkClient);
    System.out.println("END " + clusterName + " at " + new Date(System.currentTimeMillis()));
}

