    List<InstanceConfig> instanceConfigs = _gSetupTool.getClusterManagementTool().getInstancesInCluster(CLUSTER_NAME).stream().map(instanceName -> _gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceName)).collect(Collectors.toList());
