/**
 * Create resources and see if things get rebalanced correctly.
 * Helix Java API tested in this methods are:
 * ZkBaseDataAccessor
 * ZkHelixClusterVerifier (BestPossible)
 */
@Test(dependsOnMethods = "testZkUtil")
public void testCreateAndRebalanceResources() {
    String methodName = TestHelper.getTestMethodName();
    System.out.println("START " + _className + "_" + methodName + " at " + new Date(System.currentTimeMillis()));
    BaseDataAccessor<ZNRecord> dataAccessorZkAddr = new ZkBaseDataAccessor<>("DummyZk");
    BaseDataAccessor<ZNRecord> dataAccessorBuilder = new ZkBaseDataAccessor.Builder<ZNRecord>().build();
    String resourceNamePrefix = "DB_";
    int numResources = 5;
    int numPartitions = 3;
    Map<String, Map<String, ZNRecord>> idealStateMap = new HashMap<>();
    for (String cluster : CLUSTER_LIST) {
        Set<String> resourceNames = new HashSet<>();
        Set<String> liveInstancesNames = new HashSet<>(dataAccessorZkAddr.getChildNames("/" + cluster + "/LIVEINSTANCES", AccessOption.PERSISTENT));
        for (int i = 0; i < numResources; i++) {
            String resource = cluster + "_" + resourceNamePrefix + i;
            _zkHelixAdmin.addResource(cluster, resource, numPartitions, "MasterSlave", IdealState.RebalanceMode.FULL_AUTO.name(), CrushEdRebalanceStrategy.class.getName());
            _zkHelixAdmin.rebalance(cluster, resource, 3);
            resourceNames.add(resource);
            // Update IdealState fields with ZkBaseDataAccessor
            String resourcePath = "/" + cluster + "/IDEALSTATES/" + resource;
            ZNRecord is = dataAccessorZkAddr.get(resourcePath, null, AccessOption.PERSISTENT);
            is.setSimpleField(RebalanceConfig.RebalanceConfigProperty.REBALANCER_CLASS_NAME.name(), DelayedAutoRebalancer.class.getName());
            is.setSimpleField(RebalanceConfig.RebalanceConfigProperty.REBALANCE_STRATEGY.name(), CrushEdRebalanceStrategy.class.getName());
            dataAccessorZkAddr.set(resourcePath, is, AccessOption.PERSISTENT);
            idealStateMap.computeIfAbsent(cluster, recordList -> new HashMap<>()).putIfAbsent(is.getId(), // Save ZNRecord for comparison later
            is);
        }
        // Create a verifier to make sure all resources have been rebalanced
        ZkHelixClusterVerifier verifier = new BestPossibleExternalViewVerifier.Builder(cluster).setResources(resourceNames).setExpectLiveInstances(liveInstancesNames).setWaitTillVerify(TestHelper.DEFAULT_REBALANCE_PROCESSING_WAIT_TIME).build();
        try {
            Assert.assertTrue(verifier.verifyByPolling());
        } finally {
            verifier.close();
        }
    }
    // Using the ZkBaseDataAccessor created using the Builder, check that the correct IS is read
    for (String cluster : CLUSTER_LIST) {
        Map<String, ZNRecord> savedIdealStates = idealStateMap.get(cluster);
        List<String> resources = dataAccessorBuilder.getChildNames("/" + cluster + "/IDEALSTATES", AccessOption.PERSISTENT);
        resources.forEach(resource -> {
            ZNRecord is = dataAccessorBuilder.get("/" + cluster + "/IDEALSTATES/" + resource, null, AccessOption.PERSISTENT);
            Assert.assertEquals(is.getSimpleFields(), savedIdealStates.get(is.getId()).getSimpleFields());
        });
    }
    dataAccessorZkAddr.close();
    dataAccessorBuilder.close();
    System.out.println("END " + _className + "_" + methodName + " at " + new Date(System.currentTimeMillis()));
}

