    Assert.assertEquals(liveInstance.getStatus(), LiveInstance.LiveInstanceStatus.FROZEN);
    // New session path does not exist since no current state carry over for the current session.
    Assert.assertFalse(_gZkClient.exists(_keyBuilder.currentStates(_instanceName, currentSession).getPath()));
    // Old session CS still exist.
    Assert.assertTrue(_gZkClient.exists(_keyBuilder.currentStates(_instanceName, _originSession).getPath()));
}

@Test(dependsOnMethods = "testHandleNewSessionWhenFrozen")
public void testUnfreezeParticipant() throws Exception {
    Message unfreezeMessage = MessageUtil.createStatusChangeMessage(LiveInstance.LiveInstanceStatus.FROZEN, LiveInstance.LiveInstanceStatus.NORMAL, _manager.getInstanceName(), _manager.getSessionId(), _instanceName, _participants[0].getSessionId());
    List<PropertyKey> keys = Collections.singletonList(_keyBuilder.message(unfreezeMessage.getTgtName(), unfreezeMessage.getId()));
    boolean[] success = _accessor.createChildren(keys, Collections.singletonList(unfreezeMessage));
