    // Process instance -> number of assigned partitions
    ExternalView TGTDBView = _gSetupTool.getClusterManagementTool().getResourceExternalView(CLUSTER_NAME, WorkflowGenerator.DEFAULT_TGT_DB);
    ExternalView newDBView = _gSetupTool.getClusterManagementTool().getResourceExternalView(CLUSTER_NAME, "NewDB");
    Map<String, Integer> instancePartitionCountMap = new HashMap<>();
    TGTDBView.getPartitionSet().stream().forEach(partition -> TGTDBView.getStateMap(partition).keySet().forEach(instance -> {
        instancePartitionCountMap.put(instance, instancePartitionCountMap.getOrDefault(instance, 0) + 1);
    }));
    newDBView.getPartitionSet().stream().forEach(partition -> newDBView.getStateMap(partition).keySet().forEach(instance -> {
        instancePartitionCountMap.put(instance, instancePartitionCountMap.getOrDefault(instance, 0) + 1);
    }));
