@Test(dependsOnMethods = "testNodeSwapSwapInNodeWithAlreadySwappingPair")
public void testNodeSwap() throws Exception {
    System.out.println("START TestInstanceOperation.testNodeSwap() at " + new Date(System.currentTimeMillis()));
    Map<String, String> swapOutInstancesToSwapInInstances = new HashMap<>();
    String instanceToSwapOutName = _participants.get(0).getInstanceName();
    InstanceConfig instanceToSwapOutInstanceConfig = _gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceToSwapOutName);
    Assert.assertTrue(_clusterVerifier.verifyByPolling());
    String resourceToDisablePartition = _allDBs.iterator().next();
    // Disable 1 partition that is assigned to the instance that will be swapped out.
    getPartitionsAndStatesOnInstance(getEVs(), instanceToSwapOutName).entrySet().stream().filter(entry -> entry.getKey().startsWith(resourceToDisablePartition)).findFirst().ifPresent(entry -> {
        String partition = entry.getKey();
        instanceToSwapOutInstanceConfig.setInstanceEnabledForPartition(resourceToDisablePartition, partition, false);
    });
    _gSetupTool.getClusterManagementTool().setInstanceConfig(CLUSTER_NAME, instanceToSwapOutName, instanceToSwapOutInstanceConfig);
    Assert.assertTrue(_clusterVerifier.verifyByPolling());
    // Store original EV
    Map<String, ExternalView> originalEVs = getEVs();
    validateEVsCorrect(getEVs(), originalEVs, swapOutInstancesToSwapInInstances, Collections.emptySet(), Collections.emptySet());
    // Create a custom change listener to check if the throttles are enabled after the swap is completed.
    CustomIndividualInstanceConfigChangeListener instanceToSwapInInstanceConfigListener = new CustomIndividualInstanceConfigChangeListener();
    // Add instance with InstanceOperation set to SWAP_IN
    String instanceToSwapInName = PARTICIPANT_PREFIX + "_" + _nextStartPort;
    swapOutInstancesToSwapInInstances.put(instanceToSwapOutName, instanceToSwapInName);
    addParticipant(instanceToSwapInName, instanceToSwapOutInstanceConfig.getLogicalId(LOGICAL_ID), instanceToSwapOutInstanceConfig.getDomainAsMap().get(ZONE), InstanceConstants.InstanceOperation.SWAP_IN, -1, instanceToSwapInInstanceConfigListener, null);
    // Validate that the throttles are off since the InstanceOperation is set to SWAP_IN
    Assert.assertFalse(instanceToSwapInInstanceConfigListener.isThrottlesEnabled());
    // Check that the SWAP_IN instance has the same partitions as the swap out instance
    // but none of them are in a top state.
    Assert.assertTrue(_bestPossibleClusterVerifier.verifyByPolling());
    validateEVsCorrect(getEVs(), originalEVs, swapOutInstancesToSwapInInstances, ImmutableSet.of(instanceToSwapInName), Collections.emptySet());
    // Assert canSwapBeCompleted is true
    Assert.assertTrue(_gSetupTool.getClusterManagementTool().canCompleteSwap(CLUSTER_NAME, instanceToSwapOutName));
    // Validate that the swap out instance is in routing tables and SWAP_IN is not.
    validateRoutingTablesInstance(getEVs(), instanceToSwapOutName, true);
    validateRoutingTablesInstance(getEVs(), instanceToSwapInName, false);
    // Assert completeSwapIfPossible is true
    Assert.assertTrue(_gSetupTool.getClusterManagementTool().completeSwapIfPossible(CLUSTER_NAME, instanceToSwapOutName, false));
    // Get both instanceConfigs and make sure correct fields are copied over.
    InstanceConfig instanceToSwapInInstanceConfig = _gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceToSwapInName);
    Assert.assertEquals(instanceToSwapInInstanceConfig.getRecord().getMapField(InstanceConfig.InstanceConfigProperty.HELIX_DISABLED_PARTITION.name()), instanceToSwapOutInstanceConfig.getRecord().getMapField(InstanceConfig.InstanceConfigProperty.HELIX_DISABLED_PARTITION.name()));
    Assert.assertTrue(_clusterVerifier.verifyByPolling());
    // Validate that the SWAP_IN instance is now in the routing tables.
    validateRoutingTablesInstance(getEVs(), instanceToSwapInName, true);
    // Assert that swap out instance is not active and has no partitions assigned to it.
    Assert.assertFalse(_gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceToSwapOutName).getInstanceEnabled());
    Assert.assertEquals(_gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceToSwapOutName).getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.UNKNOWN);
    // Check to make sure the throttle was enabled again after the swap was completed.
    Assert.assertTrue(instanceToSwapInInstanceConfigListener.isThrottlesEnabled());
    // Validate that the SWAP_IN instance has the same partitions the swap out instance had before
    // swap was completed.
    verifier(() -> (validateEVsCorrect(getEVs(), originalEVs, swapOutInstancesToSwapInInstances, Collections.emptySet(), ImmutableSet.of(instanceToSwapInName))), TIMEOUT);
    InstanceConfig instanceToSwapInInstanceConfigAfterSwap = _gSetupTool.getClusterManagementTool().getInstanceConfig(CLUSTER_NAME, instanceToSwapInName);
    instanceToSwapInInstanceConfigAfterSwap.setInstanceEnabledForPartition(resourceToDisablePartition, true);
    _gSetupTool.getClusterManagementTool().setInstanceConfig(CLUSTER_NAME, instanceToSwapInName, instanceToSwapInInstanceConfigAfterSwap);
}

