    // Check that the SWAP_IN instance has the same partitions as the swap out instance
    // but none of them are in a top state.
    Assert.assertTrue(_bestPossibleClusterVerifier.verifyByPolling());
    validateEVsCorrect(getEVs(), originalEVs, swapOutInstancesToSwapInInstances, ImmutableSet.of(instanceToSwapInName), Collections.emptySet());
    // Assert canSwapBeCompleted is true
    Assert.assertTrue(_gSetupTool.getClusterManagementTool().canCompleteSwap(CLUSTER_NAME, instanceToSwapOutName));
    // Try to disable the swap out instance, it should not do anything.
    _gSetupTool.getClusterManagementTool().enableInstance(CLUSTER_NAME, instanceToSwapOutName, false);
    // Check that the SWAP_IN instance's replicas match the SWAP_OUT instance's replicas
    // and all of them are OFFLINE.
    Assert.assertTrue(_bestPossibleClusterVerifier.verifyByPolling());
    Map<String, Map<String, String>> resourcePartitionStateOnSwapOutInstance = getResourcePartitionStateOnInstance(getEVs(), instanceToSwapOutName);
    Map<String, Map<String, String>> resourcePartitionStateOnSwapInInstance = getResourcePartitionStateOnInstance(getEVs(), instanceToSwapInName);
