@Test
public void testCurrentStatesRoutingTableIgnoreTaskCurrentStates() throws Exception {
    FlaggedCurrentStateRoutingTableProvider routingTableCurrentStates = new FlaggedCurrentStateRoutingTableProvider(_manager);
    Assert.assertFalse(routingTableCurrentStates.isOnStateChangeTriggered());
    try {
        TaskDriver taskDriver = new TaskDriver(_manager);
        String workflowName1 = TestHelper.getTestMethodName() + "_1";
        String jobName = "JOB0";
        JobConfig.Builder jobBuilder = new JobConfig.Builder().setWorkflow(workflowName1).setNumberOfTasks(NUM_NODES).setNumConcurrentTasksPerInstance(1).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "1000"));
        Workflow.Builder workflowBuilder1 = new Workflow.Builder(workflowName1).addJob(jobName, jobBuilder);
        taskDriver.start(workflowBuilder1.build());
        taskDriver.pollForJobState(workflowName1, TaskUtil.getNamespacedJobName(workflowName1, jobName), TaskState.COMPLETED);
        Assert.assertFalse(routingTableCurrentStates.isOnStateChangeTriggered());
        // Disable the task current path and the routing table provider should be notified
        System.setProperty(SystemPropertyKeys.TASK_CURRENT_STATE_PATH_DISABLED, "true");
        String workflowName2 = TestHelper.getTestMethodName() + "_2";
        Workflow.Builder workflowBuilder2 = new Workflow.Builder(workflowName2).addJob(jobName, jobBuilder);
        taskDriver.start(workflowBuilder2.build());
        taskDriver.pollForJobState(workflowName2, TaskUtil.getNamespacedJobName(workflowName2, jobName), TaskState.COMPLETED);
        Assert.assertTrue(routingTableCurrentStates.isOnStateChangeTriggered());
        System.setProperty(SystemPropertyKeys.TASK_CURRENT_STATE_PATH_DISABLED, "false");
        String dbName = "testDB";
        _gSetupTool.addResourceToCluster(CLUSTER_NAME, dbName, NUM_PARTITIONS, "MasterSlave", IdealState.RebalanceMode.FULL_AUTO.name(), CrushEdRebalanceStrategy.class.getName());
        _gSetupTool.rebalanceStorageCluster(CLUSTER_NAME, dbName, NUM_REPLICAS);
        ZkHelixClusterVerifier clusterVerifier = new BestPossibleExternalViewVerifier.Builder(CLUSTER_NAME).setZkClient(_gZkClient).setWaitTillVerify(TestHelper.DEFAULT_REBALANCE_PROCESSING_WAIT_TIME).build();
        Assert.assertTrue(clusterVerifier.verifyByPolling());
        Assert.assertTrue(routingTableCurrentStates.isOnStateChangeTriggered());
        _gSetupTool.dropResourceFromCluster(CLUSTER_NAME, dbName);
    } finally {
        routingTableCurrentStates.shutdown();
    }
}

