@Test(dependsOnMethods = "testDeleteNonExistedTask")
public void testDeleteTaskFromJobNotStarted() throws Exception {
    String workflowName = TestHelper.getTestMethodName();
    String jobName = "JOB0";
    JobConfig.Builder jobBuilder1 = new JobConfig.Builder().setWorkflow(workflowName).setExecutionDelay(500000L).setNumberOfTasks(1).setNumConcurrentTasksPerInstance(100).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "1000"));
    Workflow.Builder workflowBuilder1 = new Workflow.Builder(workflowName).addJob(jobName, jobBuilder1);
    _driver.start(workflowBuilder1.build());
