@Test(dependsOnMethods = "testAddAndDeleteTask")
public void testDeleteTaskAndJobCompleted() throws Exception {
    String workflowName = TestHelper.getTestMethodName();
    String jobName = "JOB0";
    JobConfig.Builder jobBuilder1 = new JobConfig.Builder().setWorkflow(workflowName).setNumberOfTasks(1).setNumConcurrentTasksPerInstance(100).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "20000"));
    Workflow.Builder workflowBuilder1 = new Workflow.Builder(workflowName).addJob(jobName, jobBuilder1);
    _driver.start(workflowBuilder1.build());
    _driver.pollForJobState(workflowName, TaskUtil.getNamespacedJobName(workflowName, jobName), TaskState.IN_PROGRESS);
    // Wait until initial task goes to RUNNING state
    Assert.assertTrue(TestHelper.verify(() -> {
        JobContext jobContext = _driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName));
        if (jobContext == null) {
            return false;
        }
        TaskPartitionState state = jobContext.getPartitionState(0);
        if (state == null) {
            return false;
        }
        return (state == TaskPartitionState.RUNNING);
    }, TestHelper.WAIT_DURATION));
    // Add new task
    Map<String, String> taskConfig1 = new HashMap<String, String>(ImmutableMap.of(MockTask.JOB_DELAY, "99999999"));
    Map<String, String> taskConfig2 = new HashMap<String, String>(ImmutableMap.of(MockTask.JOB_DELAY, "99999999"));
    TaskConfig task1 = new TaskConfig(null, taskConfig1, null, null);
    TaskConfig task2 = new TaskConfig(null, taskConfig2, null, null);
    _driver.addTask(workflowName, jobName, task1);
    _driver.addTask(workflowName, jobName, task2);
    // Wait until new task goes to RUNNING state
    Assert.assertTrue(TestHelper.verify(() -> {
        JobContext jobContext = _driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName));
        if (jobContext == null) {
            return false;
        }
        TaskPartitionState state1 = jobContext.getPartitionState(1);
        TaskPartitionState state2 = jobContext.getPartitionState(2);
