    _driver.pollForWorkflowState(workflowName1, TaskState.COMPLETED);
    int initialWorkflowContextVersion = _manager.getHelixDataAccessor().getProperty(_manager.getHelixDataAccessor().keyBuilder().workflowContextZNode(workflowName1)).getRecord().getVersion();
