    JobConfig.Builder jobBuilder1 = new JobConfig.Builder().setWorkflow(workflowName).setNumberOfTasks(1).setNumConcurrentTasksPerInstance(100).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "99999999"));
