    String namespacedJobName = TaskUtil.getNamespacedJobName(workflowName, jobName);
    // Task should be assigned to the only available instance which is participant2
    Assert.assertTrue(TestHelper.verify(() -> (TaskPartitionState.RUNNING.equals(_driver.getJobContext(namespacedJobName).getPartitionState(0)) && (PARTICIPANT_PREFIX + "_" + (_startPort + 2)).equals(_driver.getJobContext(namespacedJobName).getAssignedParticipant(0))), TestHelper.WAIT_DURATION));
    // Now start two other participants
    startParticipant(0);
    startParticipant(1);
