    ZkClient clientP2 = (ZkClient) _participants[2].getZkClient();
    String sessionIdP2 = ZkTestHelper.getSessionId(clientP2);
    String currentStatePathP2 = _manager.getHelixDataAccessor().keyBuilder().taskCurrentState(instanceP2, sessionIdP2, namespacedJobName).toString();
    Assert.assertTrue(TestHelper.verify(() -> (_manager.getHelixDataAccessor().getBaseDataAccessor().get(currentStatePathP2, new Stat(), AccessOption.PERSISTENT) != null), TestHelper.WAIT_DURATION));
    // Set the current state of participant0 and participant1 with requested state equals DROPPED
    String instanceP0 = PARTICIPANT_PREFIX + "_" + (_startPort + 0);
    ZkClient clientP0 = (ZkClient) _participants[0].getZkClient();
    String sessionIdP0 = ZkTestHelper.getSessionId(clientP0);
    String currentStatePathP0 = _manager.getHelixDataAccessor().keyBuilder().taskCurrentState(instanceP0, sessionIdP0, namespacedJobName).toString();
    String instanceP1 = PARTICIPANT_PREFIX + "_" + (_startPort + 1);
    ZkClient clientP1 = (ZkClient) _participants[1].getZkClient();
    String sessionIdP1 = ZkTestHelper.getSessionId(clientP1);
    String currentStatePathP1 = _manager.getHelixDataAccessor().keyBuilder().taskCurrentState(instanceP1, sessionIdP1, namespacedJobName).toString();
    ZNRecord record = _manager.getHelixDataAccessor().getBaseDataAccessor().get(currentStatePathP2, new Stat(), AccessOption.PERSISTENT);
    String partitionName = namespacedJobName + "_0";
    Map<String, String> newCurrentState = new HashMap<>();
    newCurrentState.put(CurrentState.CurrentStateProperty.CURRENT_STATE.name(), TaskPartitionState.RUNNING.name());
    newCurrentState.put(CurrentState.CurrentStateProperty.REQUESTED_STATE.name(), TaskPartitionState.DROPPED.name());
    record.setSimpleField(CurrentState.CurrentStateProperty.SESSION_ID.name(), sessionIdP0);
    record.setMapField(partitionName, newCurrentState);
    _manager.getHelixDataAccessor().getBaseDataAccessor().set(currentStatePathP0, record, AccessOption.PERSISTENT);
    record.setSimpleField(CurrentState.CurrentStateProperty.SESSION_ID.name(), sessionIdP1);
    _manager.getHelixDataAccessor().getBaseDataAccessor().set(currentStatePathP1, record, AccessOption.PERSISTENT);
