    Assert.assertTrue(TestHelper.verify(() -> (_manager.getHelixDataAccessor().getBaseDataAccessor().get(currentStatePathP0, new Stat(), AccessOption.PERSISTENT) == null && _manager.getHelixDataAccessor().getBaseDataAccessor().get(currentStatePathP1, new Stat(), AccessOption.PERSISTENT) == null), TestHelper.WAIT_DURATION));
