    assignCustomizedIdealState(_assignmentList1);
    JobConfig.Builder jobBuilder0 = new JobConfig.Builder().setWorkflow(jobQueueName).setTargetResource(DATABASE).setTargetPartitionStates(Sets.newHashSet(MasterSlaveSMD.States.MASTER.name())).setCommand(MockTask.TASK_COMMAND).setMaxAttemptsPerTask(maxNumberOfAttempts).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "100000"));
