    ZkHelixClusterVerifier clusterVerifier = new BestPossibleExternalViewVerifier.Builder(CLUSTER_NAME).setZkClient(_gZkClient).setResources(Sets.newHashSet(DATABASE)).setWaitTillVerify(TestHelper.DEFAULT_REBALANCE_PROCESSING_WAIT_TIME).build();
    Assert.assertTrue(clusterVerifier.verify(10 * 1000));
    // Wait until master is switched to new instance and two masters exist on two different instances
    boolean isMasterOnTwoDifferentNodes = TestHelper.verify(() -> {
