@Test(dependsOnMethods = "testStoppingQueueFailToStop")
public void testStopWorkflowInstanceOffline() throws Exception {
    // Test to check if workflow and jobs go to STOPPED state when the assigned participants of the
    // tasks are not live anymore.
    latch = new CountDownLatch(1);
    int numberOfTasks = 10;
    // Stop all participant except participant0
    for (int i = 1; i < _numNodes; i++) {
        super.stopParticipant(i);
        Assert.assertFalse(_participants[i].isConnected());
    }
    // Start a new workflow
    String workflowName = TestHelper.getTestMethodName();
    String jobName = "JOB0";
    JobConfig.Builder jobBuilder = new JobConfig.Builder().setWorkflow(workflowName).setNumberOfTasks(numberOfTasks).setNumConcurrentTasksPerInstance(100).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "99999999"));
    Workflow.Builder workflowBuilder = new Workflow.Builder(workflowName).addJob(jobName, jobBuilder);
    // Start the workflow and make sure it goes to IN_PROGRESS state.
    _driver.start(workflowBuilder.build());
    _driver.pollForJobState(workflowName, TaskUtil.getNamespacedJobName(workflowName, jobName), TaskState.IN_PROGRESS);
    // Make sure all of the tasks within the job are assigned and have RUNNING state
    String participant0 = PARTICIPANT_PREFIX + "_" + (_startPort + 0);
    for (int i = 0; i < numberOfTasks; i++) {
        final int taskNumber = i;
        Assert.assertTrue(TestHelper.verify(() -> (TaskPartitionState.RUNNING.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName)).getPartitionState(taskNumber)) && participant0.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName)).getAssignedParticipant(taskNumber))), TestHelper.WAIT_DURATION));
    }
    // STOP the workflow and make sure it goes to STOPPING state
    _driver.stop(workflowName);
    _driver.pollForJobState(workflowName, TaskUtil.getNamespacedJobName(workflowName, jobName), TaskState.STOPPING);
    // Stop the remaining participant and the controller
    _controller.syncStop();
    super.stopParticipant(0);
    // Start the controller and make sure the workflow and job go to STOPPED state
    _controller = new ClusterControllerManager(ZK_ADDR, CLUSTER_NAME, CONTROLLER_PREFIX);
    _controller.syncStart();
    // Start other participants to allow controller process the workflows. Otherwise due to no
    // global capacity, the workflows will not be processed
    for (int i = 1; i < _numNodes; i++) {
        startParticipantAndRegisterNewMockTask(i);
    }
    _driver.pollForJobState(workflowName, TaskUtil.getNamespacedJobName(workflowName, jobName), TaskState.STOPPED);
    _driver.pollForWorkflowState(workflowName, TaskState.STOPPED);
    // Make sure all of the tasks within the job are assigned and have DROPPED state
    for (int i = 0; i < numberOfTasks; i++) {
        final int taskNumber = i;
        Assert.assertTrue(TestHelper.verify(() -> (TaskPartitionState.DROPPED.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName)).getPartitionState(taskNumber)) && participant0.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName, jobName)).getAssignedParticipant(taskNumber))), TestHelper.WAIT_DURATION));
    }
    latch.countDown();
}

