    JobConfig.Builder jobBuilder3 = new JobConfig.Builder().setWorkflow(workflowName3).setNumberOfTasks(1).setCommand(MockTask.TASK_COMMAND).setJobCommandConfigMap(ImmutableMap.of(MockTask.JOB_DELAY, "99999999"));
    Workflow.Builder workflowBuilder1 = new Workflow.Builder(workflowName1).addJob(jobName, jobBuilder1);
    Workflow.Builder workflowBuilder2 = new Workflow.Builder(workflowName2).addJob(jobName, jobBuilder2);
    Workflow.Builder workflowBuilder3 = new Workflow.Builder(workflowName3).addJob(jobName, jobBuilder3);
    _driver.start(workflowBuilder1.build());
    // Make sure the JOB0 of workflow1 is started and all of the tasks are assigned to the
    // participant 0
    _driver.pollForJobState(workflowName1, TaskUtil.getNamespacedJobName(workflowName1, jobName), TaskState.IN_PROGRESS);
    String participant0 = PARTICIPANT_PREFIX + "_" + (_startPort + 0);
    for (int i = 0; i < 40; i++) {
        int finalI = i;
        Assert.assertTrue(TestHelper.verify(() -> (TaskPartitionState.RUNNING.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName1, jobName)).getPartitionState(finalI)) && participant0.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName1, jobName)).getAssignedParticipant(finalI))), TestHelper.WAIT_DURATION));
    }
    // Start the second participant
    startParticipantAndRegisterNewMockTask(1);
    _driver.start(workflowBuilder2.build());
    // Make sure the JOB0 of workflow2 is started and the only task of this job is assigned to
    // participant1
    _driver.pollForJobState(workflowName2, TaskUtil.getNamespacedJobName(workflowName2, jobName), TaskState.IN_PROGRESS);
    String participant1 = PARTICIPANT_PREFIX + "_" + (_startPort + 1);
