    // Delete the workflow1
    _driver.delete(workflowName1);
    // Since the tasks will be stuck for workflow1 after the deletion, the participant 0 is out of
    // capacity. Hence, the new tasks should be assigned to participant 1
    _driver.start(workflowBuilder3.build());
    // Make sure the JOB0 of workflow3 is started and the only task of this job is assigned to
    // participant1
    _driver.pollForJobState(workflowName3, TaskUtil.getNamespacedJobName(workflowName3, jobName), TaskState.IN_PROGRESS);
    Assert.assertTrue(TestHelper.verify(() -> (TaskPartitionState.RUNNING.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName3, jobName)).getPartitionState(0))), TestHelper.WAIT_DURATION) && participant1.equals(_driver.getJobContext(TaskUtil.getNamespacedJobName(workflowName3, jobName)).getAssignedParticipant(0)));
    latch.countDown();
    // Stop the workflow2 and workflow3
    _driver.stop(workflowName2);
    _driver.stop(workflowName3);
}

