@Test
public void testWorkflowRunningTimeout() throws Exception {
    String workflowName = TestHelper.getTestMethodName();
    String notStartedJobName = JOB_NAME + "-NotStarted";
    // 2sec expiry time
    long workflowExpiry = 2000;
    long timeout = 50;
    JobConfig.Builder jobBuilder = createJobConfigBuilder(workflowName, false, 5000);
    jobBuilder.setWorkflow(workflowName);
    // Create a workflow where job2 depends on job1. Workflow would timeout before job1 finishes
    Workflow.Builder workflowBuilder = new Workflow.Builder(workflowName).setWorkflowConfig(new WorkflowConfig.Builder(workflowName).setTimeout(timeout).setWorkFlowType(WORKFLOW_TYPE).build()).addJob(JOB_NAME, jobBuilder).addJob(notStartedJobName, jobBuilder).addParentChildDependency(JOB_NAME, notStartedJobName).setExpiry(workflowExpiry);
