        IdealState is = _gSetupTool.getClusterManagementTool().getResourceIdealState(CLUSTER_NAME, dbName);
        if (!idealState.equals(is)) {
            Thread.sleep(1000L);
        }
    }
    _gSetupTool.rebalanceStorageCluster(CLUSTER_NAME, dbName, 1);
    Assert.assertTrue(_clusterVerifier.verifyByPolling());
    Thread.sleep(2000L);
    result = TestHelper.verify(() -> {
        int numOfOnlines = 0;
        int numOfErrors = 0;
        ExternalView externalView = _gSetupTool.getClusterManagementTool().getResourceExternalView(CLUSTER_NAME, dbName);
        for (String partition : externalView.getPartitionSet()) {
            if (externalView.getStateMap(partition).values().contains("ONLINE")) {
                numOfOnlines++;
            }
            if (externalView.getStateMap(partition).values().contains("ERROR")) {
                numOfErrors++;
            }
        }
        if (numOfErrors == 4 && numOfOnlines == 6) {
            return true;
        }
        return false;
    }, TestHelper.WAIT_DURATION);
    Assert.assertTrue(result);
}

