    // instance.
    try {
        admin.setPartitionsToError(clusterName, instanceName, testResource, Arrays.asList("1", "2"));
        Assert.fail("Should throw HelixException");
    } catch (HelixException expected) {
        // This exception is expected because the instance is not alive.
        Assert.assertEquals(expected.getMessage(), String.format("Can't SET_TO_ERROR state for %s.[1, 2] on %s, because %s is not alive in cluster %s", testResource, instanceName, instanceName, clusterName));
