@Test
public void testCodehausJacksonSerializer() {
    ZNRecord record = createZnRecord();
    ZNRecordSerializer znRecordSerializer = new ZNRecordSerializer();
    CodehausJsonSerializer<ZNRecord> codehausJsonSerializer = new CodehausJsonSerializer<>(ZNRecord.class);
    byte[] codehausBytes = codehausJsonSerializer.serialize(record);
    ZNRecord deserialized = (ZNRecord) codehausJsonSerializer.deserialize(codehausBytes);
    Assert.assertEquals(deserialized, record, "Codehaus jackson serializer should work with ZNRecord");
    deserialized = (ZNRecord) znRecordSerializer.deserialize(codehausBytes);
    Assert.assertEquals(deserialized, record, "ZNRecordSerializer should deserialize bytes serialized by codehaus serializer");
    deserialized = (ZNRecord) codehausJsonSerializer.deserialize(znRecordSerializer.serialize(record));
