    // Resource name based
    // Re-initialize it because if the message exists in _taskMap, it won't be assigned again
    executor = new HelixTaskExecutor();
    factory = new MockStateModelFactory_ResourceName();
    Mockito.doReturn(factory).when(engine).getStateModelFactory(stateModelDef, HelixConstants.DEFAULT_STATE_MODEL_FACTORY);
