@Test
public void testInstanceOperationMultipleSources() throws InterruptedException {
    InstanceConfig instanceConfig = new InstanceConfig("instance1");
    // Check that the instance operation is ENABLE from the DEFAULT source
    Assert.assertEquals(instanceConfig.getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.ENABLE);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.DEFAULT);
    // Set instance operation from user source
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.DISABLE).setReason("userReason").setSource(InstanceConstants.InstanceOperationSource.USER).build());
    // Get enabled time
    long op1EnabledTime = instanceConfig.getInstanceEnabledTime();
    Thread.sleep(1000);
    // Set instance operation from automation source
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.DISABLE).setReason("automationReason").setSource(InstanceConstants.InstanceOperationSource.AUTOMATION).build());
    // Check that the enabled time is the same as op1 but the source and reason is changed to automation
    Assert.assertEquals(instanceConfig.getInstanceEnabledTime(), op1EnabledTime);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.AUTOMATION);
    Thread.sleep(1000);
    // Set instance operation from user source to be ENABLE
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.ENABLE).setSource(InstanceConstants.InstanceOperationSource.USER).build());
    // Check that the operation is DISABLE, the enabled time is the same as op1, and the source is still automation
    Assert.assertEquals(instanceConfig.getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.DISABLE);
    Assert.assertEquals(instanceConfig.getInstanceEnabledTime(), op1EnabledTime);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.AUTOMATION);
    Thread.sleep(1000);
    // Set the instance operation from the automation source to be ENABLE
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.ENABLE).setSource(InstanceConstants.InstanceOperationSource.AUTOMATION).build());
    // Check that the operation is ENABLE, the enabled time is the different from op1, and the source is still automation
    Assert.assertEquals(instanceConfig.getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.ENABLE);
    Assert.assertFalse(instanceConfig.getInstanceEnabledTime() == op1EnabledTime);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.AUTOMATION);
    // Set the instance operation from the automation source to be EVACUATE
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.EVACUATE).setSource(InstanceConstants.InstanceOperationSource.AUTOMATION).build());
    // Set the instance operation from the user source to be DISABLE
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.DISABLE).setSource(InstanceConstants.InstanceOperationSource.USER).build());
    // Check that the instance operation is DISABLE and the source is user
    Assert.assertEquals(instanceConfig.getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.DISABLE);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.USER);
    // Set the instance operation from the admin source to be ENABLE
    instanceConfig.setInstanceOperation(new InstanceConfig.InstanceOperation.Builder().setOperation(InstanceConstants.InstanceOperation.ENABLE).setSource(InstanceConstants.InstanceOperationSource.ADMIN).build());
    // Check that the instance operation is ENABLE and the source is admin
    Assert.assertEquals(instanceConfig.getInstanceOperation().getOperation(), InstanceConstants.InstanceOperation.ENABLE);
    Assert.assertEquals(instanceConfig.getInstanceOperation().getSource(), InstanceConstants.InstanceOperationSource.ADMIN);
}

@Test
public void testDataChange() throws Exception {
    // Create an admin and add LiveInstanceChange listener to it
    HelixManager adminManager = HelixManagerFactory.getZKHelixManager(clusterName, null, InstanceType.ADMINISTRATOR, ZK_ADDR);
    adminManager.connect();
    final BlockingQueue<List<LiveInstance>> changeList = new LinkedBlockingQueue<List<LiveInstance>>();
    adminManager.addLiveInstanceChangeListener(new LiveInstanceChangeListener() {

        @Override
        public void onLiveInstanceChange(List<LiveInstance> liveInstances, NotificationContext changeContext) {
            // The queue is basically unbounded, so shouldn't throw exception when calling
            // "add".
            changeList.add(deepCopy(liveInstances));
        }
    });
    // Check the initial condition
    List<LiveInstance> instances = changeList.poll(1, TimeUnit.SECONDS);
    Assert.assertNotNull(instances, "Expecting a list of live instance");
    Assert.assertTrue(instances.isEmpty(), "Expecting an empty list of live instance");
    // Join as participant, should trigger a live instance change event
    HelixManager manager = HelixManagerFactory.getZKHelixManager(clusterName, "localhost_54321", InstanceType.PARTICIPANT, ZK_ADDR);
    manager.connect();
    instances = changeList.poll(1, TimeUnit.SECONDS);
    Assert.assertNotNull(instances, "Expecting a list of live instance");
    Assert.assertEquals(instances.size(), 1, "Expecting one live instance");
    Assert.assertEquals(instances.get(0).getInstanceName(), manager.getInstanceName());
    // Update data in the live instance node, should trigger another live instance change
    // event
    HelixDataAccessor helixDataAccessor = manager.getHelixDataAccessor();
    PropertyKey propertyKey = helixDataAccessor.keyBuilder().liveInstance(manager.getInstanceName());
    LiveInstance instance = helixDataAccessor.getProperty(propertyKey);
    Map<String, String> map = new TreeMap<String, String>();
    map.put("k1", "v1");
    instance.getRecord().setMapField("test", map);
    Assert.assertTrue(helixDataAccessor.updateProperty(propertyKey, instance), "Failed to update live instance node");
    instances = changeList.poll(1, TimeUnit.SECONDS);
    Assert.assertNotNull(instances, "Expecting a list of live instance");
    Assert.assertEquals(instances.get(0).getRecord().getMapField("test"), map, "Wrong map data.");
    manager.disconnect();
    // wait for callback finish
    Thread.sleep(1000);
    instances = changeList.poll(1, TimeUnit.SECONDS);
    Assert.assertNotNull(instances, "Expecting a list of live instance");
    Assert.assertTrue(instances.isEmpty(), "Expecting an empty list of live instance");
    adminManager.disconnect();
}

