    ai.updateConfigs(null, null, createLiveInstance(new String[] { LiveInstance.InstanceResourceType.TASK_EXEC_THREAD.name() }, new String[] { "1" }));
    ai.updateConfigs(createClusterConfig(testQuotaTypes, testQuotaRatio, true), null, null);
