@Test
public void testRestoreTaskAssignResult() {
    AssignableInstance ai = new AssignableInstance(createClusterConfig(testQuotaTypes, testQuotaRatio, true), new InstanceConfig(testInstanceName), createLiveInstance(new String[] { LiveInstance.InstanceResourceType.TASK_EXEC_THREAD.name() }, new String[] { "40" }));
