@Test(dependsOnMethods = "testAddClusterWithValidCloudConfig")
public void testDropInstance() throws Exception {
    // drop without stop, should throw exception
    String className = TestHelper.getTestClassName();
    String methodName = TestHelper.getTestMethodName();
    String clusterName = className + "_" + methodName;
    String instanceAddress = "localhost:12918";
    String instanceName = "localhost_12918";
    System.out.println("START " + clusterName + " at " + new Date(System.currentTimeMillis()));
    // participant port
    TestHelper.// participant port
    setupCluster(// participant port
    clusterName, // participant port
    ZK_ADDR, // participant port
    12918, // participant name prefix
    "localhost", // resource name prefix
    "TestDB", // resources
    1, // partitions per resource
    10, // number of nodes
    5, // replicas
    3, "MasterSlave", // do rebalance
    true);
    // add fake liveInstance
    HelixDataAccessor accessor = new ZKHelixDataAccessor(clusterName, new ZkBaseDataAccessor.Builder<ZNRecord>().setRealmMode(RealmAwareZkClient.RealmMode.SINGLE_REALM).setZkClientType(ZkBaseDataAccessor.ZkClientType.DEDICATED).setZkAddress(ZK_ADDR).build());
    try {
        Builder keyBuilder = new Builder(clusterName);
        LiveInstance liveInstance = new LiveInstance(instanceName);
        liveInstance.setSessionId("session_0");
        liveInstance.setHelixVersion("version_0");
        Assert.assertTrue(accessor.setProperty(keyBuilder.liveInstance(instanceName), liveInstance));
        // Drop instance without stopping the live instance, should throw HelixException
        try {
            ClusterSetup.processCommandLineArgs(new String[] { "--zkSvr", ZK_ADDR, "--dropNode", clusterName, instanceAddress });
            Assert.fail("Should throw exception since localhost_12918 is still in LIVEINSTANCES/");
        } catch (HelixException expected) {
            Assert.assertEquals(expected.getMessage(), "Cannot drop instance " + instanceName + " as it is still live. Please stop it first");
        }
        accessor.removeProperty(keyBuilder.liveInstance(instanceName));
        // drop without disable, should throw exception
        try {
            ClusterSetup.processCommandLineArgs(new String[] { "--zkSvr", ZK_ADDR, "--dropNode", clusterName, instanceAddress });
            Assert.fail("Should throw exception since " + instanceName + " is enabled");
        } catch (HelixException expected) {
            Assert.assertEquals(expected.getMessage(), "Node " + instanceName + " is enabled, cannot drop");
        }
        // Disable the instance
        ClusterSetup.processCommandLineArgs(new String[] { "--zkSvr", ZK_ADDR, "--enableInstance", clusterName, instanceName, "false" });
        // Drop the instance
        ClusterSetup.processCommandLineArgs(new String[] { "--zkSvr", ZK_ADDR, "--dropNode", clusterName, instanceAddress });
        Assert.assertNull(accessor.getProperty(keyBuilder.instanceConfig(instanceName)), "Instance config should be dropped");
        Assert.assertFalse(_gZkClient.exists(PropertyPathBuilder.instance(clusterName, instanceName)), "Instance/host should be dropped");
    } finally {
        // Have to close the dedicated zkclient in accessor to avoid zkclient leakage.
        accessor.getBaseDataAccessor().close();
        TestHelper.dropCluster(clusterName, _gZkClient);
        // Verify the cluster has been dropped.
        Assert.assertTrue(TestHelper.verify(() -> {
            if (_gZkClient.exists("/" + clusterName)) {
                TestHelper.dropCluster(clusterName, _gZkClient);
            }
            return true;
        }, TestHelper.WAIT_DURATION));
    }
    System.out.println("END " + clusterName + " at " + new Date(System.currentTimeMillis()));
}

