@Test
public void test() throws Exception {
    String testName = "TestZKClientPool";
    System.out.println("START " + testName + " at " + new Date(System.currentTimeMillis()));
    String zkAddr = "localhost:21891";
    ZkServer zkServer = TestHelper.startZkServer(zkAddr);
    ZkClient zkClient = ZKClientPool.getZkClient(zkAddr);
    zkClient.createPersistent("/" + testName, new ZNRecord(testName));
    ZNRecord record = zkClient.readData("/" + testName);
    Assert.assertEquals(record.getId(), testName);
    TestHelper.stopZkServer(zkServer);
    // restart zk
    zkServer = TestHelper.startZkServer(zkAddr);
    try {
        zkClient = ZKClientPool.getZkClient(zkAddr);
        record = zkClient.readData("/" + testName);
        Assert.fail("should fail on zk no node exception");
    } catch (ZkNoNodeException e) {
        // OK
    } catch (Exception e) {
        Assert.fail("should not fail on exception other than ZkNoNodeException");
    }
    zkClient.createPersistent("/" + testName, new ZNRecord(testName));
    record = zkClient.readData("/" + testName);
    Assert.assertEquals(record.getId(), testName);
    zkClient.close();
    TestHelper.stopZkServer(zkServer);
    System.out.println("END " + testName + " at " + new Date(System.currentTimeMillis()));
}

@Test
public void testAcquireLock() {
    // Acquire lock
    _lock.tryLock();
    Assert.assertTrue(_gZkClient.exists(_lockPath));
    // Get lock information
    LockInfo lockInfo = _lock.getCurrentLockInfo();
    Assert.assertEquals(lockInfo.getOwner(), _userId);
    Assert.assertEquals(lockInfo.getMessage(), _lockMessage);
    // Check if the user is lock owner
    Assert.assertTrue(_lock.isCurrentOwner());
    // Release lock
    _lock.unlock();
    Assert.assertFalse(_lock.isCurrentOwner());
}

@Test
public void testAcquireLockWhenExistingLockNotExpired() {
    // Fake condition when the lock owner is not current user
    String fakeUserID = UUID.randomUUID().toString();
    ZNRecord fakeRecord = new ZNRecord(fakeUserID);
    fakeRecord.setSimpleField(LockInfo.LockInfoAttribute.OWNER.name(), fakeUserID);
    fakeRecord.setSimpleField(LockInfo.LockInfoAttribute.TIMEOUT.name(), String.valueOf(Long.MAX_VALUE));
    fakeRecord.setIntField(LockInfo.LockInfoAttribute.PRIORITY.name(), 0);
    _gZkClient.create(_lockPath, fakeRecord, CreateMode.PERSISTENT);
    // Check if the user is lock owner
    Assert.assertFalse(_lock.isCurrentOwner());
    // Acquire lock
    Assert.assertFalse(_lock.tryLock());
    Assert.assertFalse(_lock.isCurrentOwner());
    // Release lock
    Assert.assertFalse(_lock.unlock());
}

@Test
public void testAcquireLockWhenExistingLockExpired() {
    // Fake condition when the current lock already expired
    String fakeUserID = UUID.randomUUID().toString();
    ZNRecord fakeRecord = new ZNRecord(fakeUserID);
    fakeRecord.setSimpleField(LockInfo.LockInfoAttribute.OWNER.name(), fakeUserID);
    fakeRecord.setSimpleField(LockInfo.LockInfoAttribute.TIMEOUT.name(), String.valueOf(System.currentTimeMillis()));
    fakeRecord.setIntField(LockInfo.LockInfoAttribute.PRIORITY.name(), 0);
    _gZkClient.create(_lockPath, fakeRecord, CreateMode.PERSISTENT);
    // Acquire lock
    Assert.assertTrue(_lock.tryLock());
    Assert.assertTrue(_lock.isCurrentOwner());
    // Release lock
    Assert.assertTrue(_lock.unlock());
    Assert.assertFalse(_lock.isCurrentOwner());
