@Test
public void testHigherPriorityRequestPreemptedByAnother() throws Exception {
    ZKDistributedNonblockingLock lock = createLockWithConfig();
    ZKDistributedNonblockingLock.Builder lockBuilder = new ZKDistributedNonblockingLock.Builder();
    lockBuilder.setLockScope(_participantScope).setZkAddress(ZK_ADDR).setTimeout(3600000L).setLockMsg("higher priority lock").setUserId("high_lock").setPriority(2).setWaitingTimeout(30000).setCleanupTimeout(10000).setIsForceful(false).setLockListener(createLockListener());
    ZKDistributedNonblockingLock higherLock = lockBuilder.build();
    ZKDistributedNonblockingLock.Builder highestLockBuilder = new ZKDistributedNonblockingLock.Builder();
    highestLockBuilder.setLockScope(_participantScope).setZkAddress(ZK_ADDR).setTimeout(3600000L).setLockMsg("highest priority lock").setUserId("highest_lock").setPriority(3).setWaitingTimeout(30000).setCleanupTimeout(10000).setIsForceful(false).setLockListener(createLockListener());
    ZKDistributedNonblockingLock highestLock = highestLockBuilder.build();
    Thread t = new Thread() {

        @Override
        public void run() {
            lock.tryLock();
        }
    };
    Thread t_highest = new Thread() {

        @Override
        public void run() {
            highestLock.tryLock();
        }
    };
    t.start();
    t.join();
    Assert.assertTrue(lock.isCurrentOwner());
    LockHelper lockHelper = new LockHelper(higherLock);
    Thread t_higher = new Thread(lockHelper);
