                return _metadataStoreDirectory.getAllShardingKeys(namespace).contains(newKey) && _metadataStoreDirectory.getAllShardingKeysInRealm(namespace, TEST_REALM_3).contains(newKey);
            } catch (NoSuchElementException e) {
                // Pass - wait until callback is called
            }
        }
