@Test(dependsOnMethods = "testChildChangeCallback")
public void testDataDeletionCallback() throws Exception {
    // For all namespaces, delete all routing data
    _zkList.forEach(zk -> {
        ZkClient zkClient = ZK_SERVER_MAP.get(zk).getZkClient();
        if (zkClient.exists(MetadataStoreRoutingConstants.ROUTING_DATA_PATH)) {
            for (String zkRealm : zkClient.getChildren(MetadataStoreRoutingConstants.ROUTING_DATA_PATH)) {
                zkClient.delete(MetadataStoreRoutingConstants.ROUTING_DATA_PATH + "/" + zkRealm);
            }
        }
    });
    // Confirm that TrieRoutingData has been removed due to missing routing data
    Assert.assertTrue(TestHelper.verify(() -> {
        for (String namespace : _routingZkAddrMap.keySet()) {
            try {
                _metadataStoreDirectory.getMetadataStoreRealm(namespace, TEST_SHARDING_KEYS_1.get(0));
                // Metadata store realm is not yet refreshed. Retry.
                return false;
            } catch (IllegalStateException e) {
                // If other IllegalStateException, it is unexpected and this test should fail.
                if (!e.getMessage().equals("Failed to get metadata store realm: Namespace " + namespace + " contains either empty or invalid routing data!")) {
                    throw e;
                }
            }
        }
        return true;
    }, TestHelper.WAIT_DURATION));
}

