@Test(dependsOnMethods = "testDefaultAuthValidator")
public void testCustomAuthValidator() throws IOException, InterruptedException {
    int newPort = getBaseUri().getPort() + 1;
    // Start a second server for testing Distributed Leader Election for writes
    _mockBaseUri = HttpConstants.HTTP_PROTOCOL_PREFIX + getBaseUri().getHost() + ":" + newPort;
    _httpClient = HttpClients.createDefault();
    AuthValidator mockAuthValidatorPass = Mockito.mock(AuthValidator.class);
    when(mockAuthValidatorPass.validate(any())).thenReturn(true);
    AuthValidator mockAuthValidatorReject = Mockito.mock(AuthValidator.class);
    when(mockAuthValidatorReject.validate(any())).thenReturn(false);
    List<HelixRestNamespace> namespaces = new ArrayList<>();
    namespaces.add(new HelixRestNamespace(HelixRestNamespace.DEFAULT_NAMESPACE_NAME, HelixRestNamespace.HelixMetadataStoreType.ZOOKEEPER, ZK_ADDR, true));
    // Create a server that allows operations based on namespace auth and rejects operations based
    // on cluster auth
    HelixRestServer server = new HelixRestServer(namespaces, newPort, getBaseUri().getPath(), Collections.emptyList(), mockAuthValidatorReject, mockAuthValidatorPass, new NoopAclRegister());
    server.start();
    HttpUriRequest request = buildRequest("/clusters/" + CLASSNAME_TEST_CST_AUTH, HttpConstants.RestVerbs.PUT, "");
    sendRequestAndValidate(request, Response.Status.CREATED.getStatusCode());
    request = buildRequest("/clusters/" + CLASSNAME_TEST_CST_AUTH, HttpConstants.RestVerbs.GET, "");
    sendRequestAndValidate(request, Response.Status.FORBIDDEN.getStatusCode());
    server.shutdown();
    _httpClient.close();
    // Create a server that rejects operations based on namespace auth and allows operations based
    // on cluster auth
    server = new HelixRestServer(namespaces, newPort, getBaseUri().getPath(), Collections.emptyList(), mockAuthValidatorPass, mockAuthValidatorReject, new NoopAclRegister());
    server.start();
    _httpClient = HttpClients.createDefault();
    request = buildRequest("/clusters/" + CLASSNAME_TEST_CST_AUTH, HttpConstants.RestVerbs.GET, "");
    sendRequestAndValidate(request, Response.Status.OK.getStatusCode());
    request = buildRequest("/clusters", HttpConstants.RestVerbs.GET, "");
    sendRequestAndValidate(request, Response.Status.FORBIDDEN.getStatusCode());
    server.shutdown();
    _httpClient.close();
}

@Test
public void testValidateClusterConfigChange() throws IOException {
    System.out.println("Start test :" + TestHelper.getTestMethodName());
    String cluster = "TestCluster_1";
    ClusterConfig config = getClusterConfigFromRest(cluster);
    // Enable the topology aware setting while the instance config does not have the DOMAIN info
    {
        ClusterConfig newConfig = new ClusterConfig(config.getRecord());
        newConfig.setTopologyAwareEnabled(true);
        _auditLogger.clearupLogs();
        Entity entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(newConfig.getRecord()), MediaType.APPLICATION_JSON_TYPE);
        post("clusters/" + cluster + "/configs", ImmutableMap.of("command", Command.update.name()), entity, Response.Status.INTERNAL_SERVER_ERROR.getStatusCode());
        validateAuditLogSize(1);
        AuditLog auditLog = _auditLogger.getAuditLogs().get(0);
        Assert.assertEquals(auditLog.getHttpMethod(), HTTPMethods.POST.name());
        Assert.assertEquals(auditLog.getRequestPath(), "clusters/" + cluster + "/configs");
        Assert.assertEquals(auditLog.getExceptions().size(), 1);
    }
    // Since the topology aware is not enabled, changing the cluster config should not fail even
    // if the instance config does not have the DOMAIN info
    {
        ClusterConfig newConfig = new ClusterConfig(config.getRecord());
        newConfig.setFaultZoneType("TestZoneId");
        newConfig.setTopology("/TestZoneId/instance");
        newConfig.setTopologyAwareEnabled(false);
        updateClusterConfigFromRest(cluster, newConfig, Command.update);
    }
    // Update the topology path string to NULL. This request should go through since the
    // topology aware is not enabled.
    {
        ClusterConfig newConfig = new ClusterConfig(config.getRecord());
        newConfig.setTopology(null);
        newConfig.setFaultZoneType(null);
        newConfig.setTopologyAwareEnabled(false);
        updateClusterConfigFromRest(cluster, newConfig, Command.update);
    }
    // Now update the config while keeping the topology path and fault zone unchanged (it's still NULL)
    {
        ClusterConfig newConfig = new ClusterConfig(config.getClusterName());
        newConfig.setTopologyAwareEnabled(true);
        _auditLogger.clearupLogs();
        Entity entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(newConfig.getRecord()), MediaType.APPLICATION_JSON_TYPE);
        post("clusters/" + cluster + "/configs", ImmutableMap.of("command", Command.update.name()), entity, Response.Status.INTERNAL_SERVER_ERROR.getStatusCode());
        validateAuditLogSize(1);
        AuditLog auditLog = _auditLogger.getAuditLogs().get(0);
        Assert.assertEquals(auditLog.getHttpMethod(), HTTPMethods.POST.name());
        Assert.assertEquals(auditLog.getRequestPath(), "clusters/" + cluster + "/configs");
        Assert.assertEquals(auditLog.getExceptions().size(), 1);
    }
    // Restore the cluster config
    updateClusterConfigFromRest(cluster, config, Command.update);
    System.out.println("End test :" + TestHelper.getTestMethodName());
}

