    Assert.assertEquals(record.getMapFields(), _configAccessor.getInstanceConfig(CLUSTER_NAME, instanceName).getRecord().getMapFields());
    String newValue = "newValue";
    // 2. Modify the record and update
    for (int i = 0; i < 3; i++) {
        String key = "k" + i;
        record.getSimpleFields().put(key, newValue);
        record.getMapFields().put(key, ImmutableMap.of(key, newValue));
        record.getListFields().put(key, Arrays.asList(key, newValue));
    }
    entity = Entity.entity(OBJECT_MAPPER.writeValueAsString(record), MediaType.APPLICATION_JSON_TYPE);
    new JerseyUriRequestBuilder("clusters/{}/instances/{}/configs?command=update").format(CLUSTER_NAME, INSTANCE_NAME).post(this, entity);
