@Test
public void testDelete() {
    String parentPath = "/" + TestHelper.getTestMethodName();
    String deletePath = parentPath + "/delete";
    try {
        // 1. Create a persistent node. Delete shall fail.
        _testBaseDataAccessor.create(deletePath, null, AccessOption.PERSISTENT);
        new JerseyUriRequestBuilder("zookeeper{}").format(deletePath).expectedReturnStatusCode(Response.Status.FORBIDDEN.getStatusCode()).delete(this);
        Assert.assertTrue(_testBaseDataAccessor.exists(deletePath, AccessOption.PERSISTENT));
        // 2. Try to delete a non-exist ZNode
        new JerseyUriRequestBuilder("zookeeper{}").format(deletePath + "/foobar").expectedReturnStatusCode(Response.Status.NOT_FOUND.getStatusCode()).delete(this);
        // 3. Create an ephemeral node. Delete shall be done successfully.
        _testBaseDataAccessor.remove(deletePath, AccessOption.PERSISTENT);
        _testBaseDataAccessor.create(deletePath, null, AccessOption.EPHEMERAL);
        // Verify with the REST endpoint
        new JerseyUriRequestBuilder("zookeeper{}").format(deletePath).expectedReturnStatusCode(Response.Status.OK.getStatusCode()).delete(this);
        Assert.assertFalse(_testBaseDataAccessor.exists(deletePath, AccessOption.PERSISTENT));
    } finally {
        // Clean up
        _testBaseDataAccessor.remove(parentPath, AccessOption.PERSISTENT);
    }
}

