    for (int i = 0; i < TEST_ITERATION_COUNT; i++) {
        ops.add(Op.create(zkParentKey + "/" + i, new byte[0], PERSISTENT));
    }
    List<OpResult> opResults = _zkMetaClient.transactionOP(ops);
    for (int i = 0; i < TEST_ITERATION_COUNT; i++) {
