        return (clt1.getLeader(leaderPath) != null);
    }, MetaClientTestUtil.WAIT_DURATION));
    Assert.assertTrue(MetaClientTestUtil.verify(() -> {
        return (clt1.getLeader(leaderPath).equals(PARTICIPANT_NAME1));
    }, MetaClientTestUtil.WAIT_DURATION));
