@Test
public void testMockMetadataStoreDirectoryServer() throws IOException {
    // Start MockMSDS
    String host = "localhost";
    int port = 11000;
    String endpoint = "http://" + host + ":" + port;
    String namespace = "MY-HELIX-NAMESPACE";
    MockMetadataStoreDirectoryServer server = new MockMetadataStoreDirectoryServer(host, port, namespace, TestConstants.FAKE_ROUTING_DATA);
    server.startServer();
    try (CloseableHttpClient httpClient = HttpClients.createDefault()) {
        // Send a GET request for all routing data
        HttpGet getRequest = new HttpGet(endpoint + MockMetadataStoreDirectoryServer.REST_PREFIX + namespace + MetadataStoreRoutingConstants.MSDS_GET_ALL_ROUTING_DATA_ENDPOINT);
        CloseableHttpResponse getResponse = httpClient.execute(getRequest);
        Map<String, Object> resultMap = MockMetadataStoreDirectoryServer.OBJECT_MAPPER.readValue(getResponse.getEntity().getContent(), Map.class);
        List<Map<String, Object>> routingDataList = (List<Map<String, Object>>) resultMap.get(MetadataStoreRoutingConstants.ROUTING_DATA);
        Collection<String> allRealms = routingDataList.stream().map(mapEntry -> (String) mapEntry.get(MetadataStoreRoutingConstants.SINGLE_METADATA_STORE_REALM)).collect(Collectors.toSet());
        Assert.assertEquals(new HashSet(allRealms), TestConstants.FAKE_ROUTING_DATA.keySet());
        Map<String, List<String>> retrievedRoutingData = routingDataList.stream().collect(Collectors.toMap(mapEntry -> (String) mapEntry.get(MetadataStoreRoutingConstants.SINGLE_METADATA_STORE_REALM), mapEntry -> (List<String>) mapEntry.get(MetadataStoreRoutingConstants.SHARDING_KEYS)));
        Assert.assertEquals(retrievedRoutingData, TestConstants.FAKE_ROUTING_DATA);
        // Send a GET request for all realms
        getRequest = new HttpGet(endpoint + MockMetadataStoreDirectoryServer.REST_PREFIX + namespace + MockMetadataStoreDirectoryServer.ZK_REALM_ENDPOINT);
        getResponse = httpClient.execute(getRequest);
        Map<String, Collection<String>> allRealmsMap = MockMetadataStoreDirectoryServer.OBJECT_MAPPER.readValue(getResponse.getEntity().getContent(), Map.class);
        Assert.assertTrue(allRealmsMap.containsKey(MetadataStoreRoutingConstants.METADATA_STORE_REALMS));
        allRealms = allRealmsMap.get(MetadataStoreRoutingConstants.METADATA_STORE_REALMS);
        Assert.assertEquals(allRealms, TestConstants.FAKE_ROUTING_DATA.keySet());
        // Send a GET request for testZkRealm
        String testZkRealm = "zk-0";
        getRequest = new HttpGet(endpoint + MockMetadataStoreDirectoryServer.REST_PREFIX + namespace + MockMetadataStoreDirectoryServer.ZK_REALM_ENDPOINT + "/" + testZkRealm);
        getResponse = httpClient.execute(getRequest);
        Map<String, Object> shardingKeysMap = MockMetadataStoreDirectoryServer.OBJECT_MAPPER.readValue(getResponse.getEntity().getContent(), Map.class);
        Assert.assertTrue(shardingKeysMap.containsKey(MetadataStoreRoutingConstants.SINGLE_METADATA_STORE_REALM));
        Assert.assertTrue(shardingKeysMap.containsKey(MetadataStoreRoutingConstants.SHARDING_KEYS));
        String zkRealm = (String) shardingKeysMap.get(MetadataStoreRoutingConstants.SINGLE_METADATA_STORE_REALM);
        Collection<String> shardingKeyList = (Collection) shardingKeysMap.get(MetadataStoreRoutingConstants.SHARDING_KEYS);
        Assert.assertEquals(zkRealm, testZkRealm);
        Assert.assertEquals(shardingKeyList, TestConstants.FAKE_ROUTING_DATA.get(testZkRealm));
        // Try sending a POST request (not supported)
        HttpPost postRequest = new HttpPost(endpoint + MockMetadataStoreDirectoryServer.REST_PREFIX + namespace + MockMetadataStoreDirectoryServer.ZK_REALM_ENDPOINT + "/" + testZkRealm);
        CloseableHttpResponse postResponse = httpClient.execute(postRequest);
    } finally {
        // Shutdown
        server.stopServer();
    }
}

/*
   * Tests data serializing when auto compression is disabled. If the system property for
   * auto compression is set to "false", auto compression is disabled.
   */
@Test
public void testAutoCompressionDisabled() {
    // Backup properties for later resetting.
    final String compressionEnabledProperty = System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_ENABLED);
    final String compressionThresholdProperty = System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES);
    try {
        // Prepare system properties to disable auto compression.
        final int writeSizeLimit = 200 * 1024;
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES, String.valueOf(writeSizeLimit));
        // 2. Set the auto compression enabled property to false so auto compression is disabled.
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_ENABLED, "false");
        // Verify auto compression is disabled.
        Assert.assertFalse(Boolean.getBoolean(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_ENABLED));
        // Data size 300 KB > size limit 200 KB: exception expected.
        verifyAutoCompression(300, false, true);
        // Data size 100 KB < size limit 200 KB: pass
        verifyAutoCompression(100, false, false);
    } finally {
        // Reset: add the properties back to system properties if they were originally available.
        if (compressionEnabledProperty != null) {
            System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_ENABLED, compressionEnabledProperty);
        } else {
            System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_ENABLED);
        }
        if (compressionThresholdProperty != null) {
            System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES, compressionThresholdProperty);
        } else {
            System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES);
        }
    }
}

/*
   * Tests data serializing when compress threshold is set.
   * Two cases:
   * 1. threshold is not set
   * --> default threshold (write size limit is used): pass or throw exception.
   * 2. threshold is set
   * --> serialized data is checked by the threshold.
   */
@Test
public void testZNRecordSerializerWriteSizeLimit() {
    // Backup properties for later resetting.
    final String writeSizeLimitProperty = System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES);
    final String compressThresholdProperty = System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES);
    try {
        // Unset write size limit and compress threshold properties so default limit is used.
        System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES);
        System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES);
        Assert.assertNull(System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES));
        Assert.assertNull(System.getProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES));
        verifyAutoCompression(600, false, false);
        // 1. Set size limit but no compression threshold.
        final int writeSizeLimit = 200 * 1024;
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES, String.valueOf(writeSizeLimit));
        // Data size 100 KB < size limit 200 KB: directly write without compression.
        verifyAutoCompression(100, false, false);
        // Data size 300 KB > size limit 200 KB: compress expected.
        verifyAutoCompression(300, true, false);
        // 2. Set threshold so serialized compressed data even the size is smaller than the size limit.
        // Set it to 2000 bytes
        final int threshold = 100 * 1024;
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES, String.valueOf(threshold));
        // Data size 150 KB < size limit 200 KB and > threshold 100 KB: compress expected.
        verifyAutoCompression(150, true, false);
        // 3. Set threshold to be larger than the write size limit. The default value will be used.
        int doubleLimitThreshold = writeSizeLimit * 2;
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES, String.valueOf(doubleLimitThreshold));
        // Data size 250 KB > size limit 200 KB but < threshold 400 KB: compress is still expected.
        verifyAutoCompression(250, true, false);
        // 4. Set threshold to zero so compression will always be done.
        System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES, String.valueOf(0));
        // Data size 250 KB > size limit 200 KB but < threshold 400 KB: compress is still expected.
        verifyAutoCompression(5, true, false);
    } finally {
        // Reset: add the properties back to system properties if they were originally available.
        if (writeSizeLimitProperty != null) {
            System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES, writeSizeLimitProperty);
        } else {
            System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_WRITE_SIZE_LIMIT_BYTES);
        }
        if (compressThresholdProperty != null) {
            System.setProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES, compressThresholdProperty);
        } else {
            System.clearProperty(ZkSystemPropertyKeys.ZK_SERIALIZER_ZNRECORD_AUTO_COMPRESS_THRESHOLD_BYTES);
        }
    }
}

/**
 * 1. Create a RealmAwareZkClient with a non-existing sharding key (for which there is no valid ZK realm)
 * -> This should fail with an exception
 * 2. Create a RealmAwareZkClient with a valid sharding key
 * -> This should pass
 */
@Test
public void testRealmAwareZkClientCreation() {
    // Create a RealmAwareZkClient
    String invalidShardingKey = "InvalidShardingKeyNoLeadingSlash";
    RealmAwareZkClient.RealmAwareZkClientConfig clientConfig = new RealmAwareZkClient.RealmAwareZkClientConfig();
    // Create a connection config with the invalid sharding key
    RealmAwareZkClient.RealmAwareZkConnectionConfig.Builder builder = new RealmAwareZkClient.RealmAwareZkConnectionConfig.Builder();
    RealmAwareZkClient.RealmAwareZkConnectionConfig connectionConfig = builder.setZkRealmShardingKey(invalidShardingKey).build();
    try {
        _realmAwareZkClient = _realmAwareZkClientFactory.buildZkClient(connectionConfig, clientConfig);
        Assert.fail("Should not succeed with an invalid sharding key!");
    } catch (IllegalArgumentException e) {
        // Expected because invalid sharding key would cause an IllegalArgumentException to be thrown
    } catch (Exception e) {
        Assert.fail("Should not see any other types of Exceptions: " + e);
    }
    // Create a connection config with a valid sharding key, but one that does not exist in
    // the routing data
    String nonExistentShardingKey = "/NonExistentShardingKey";
    connectionConfig = builder.setZkRealmShardingKey(nonExistentShardingKey).build();
    try {
        _realmAwareZkClient = _realmAwareZkClientFactory.buildZkClient(connectionConfig, clientConfig);
        Assert.fail("Should not succeed with a non-existent sharding key!");
    } catch (NoSuchElementException e) {
        // Expected non-existent sharding key would cause a NoSuchElementException to be thrown
    } catch (Exception e) {
        Assert.fail("Should not see any other types of Exceptions: " + e);
    }
    // Use a valid sharding key this time around
    connectionConfig = builder.setZkRealmShardingKey(ZK_SHARDING_KEY_PREFIX).build();
    try {
        _realmAwareZkClient = _realmAwareZkClientFactory.buildZkClient(connectionConfig, clientConfig);
    } catch (Exception e) {
        Assert.fail("All other exceptions not allowed: " + e);
    }
}

