    final ObjectName name = MBeanRegistrar.buildObjectName(MonitorDomainNames.HelixZkClient.name(), ZkClientMonitor.MONITOR_TYPE, TEST_TAG, ZkClientMonitor.MONITOR_KEY, TEST_KEY);
    final int zkPort = TestHelper.getRandomPort();
    final String zkAddr = String.format("localhost:%d", zkPort);
    final ZkServer zkServer = startZkServer(zkAddr);
    try {
        ZkClient.Builder builder = new ZkClient.Builder();
        builder.setZkServer(zkAddr).setMonitorKey(TEST_KEY).setMonitorType(TEST_TAG).setMonitorRootPathOnly(true);
        final ZkClient zkClient = builder.build();
        long lastSessionId = zkClient.getSessionId();
        long previousSessionExpiredCount = (long) beanServer.getAttribute(name, "ExpiredSessionCounter");
        for (int i = 0; i < 3; i++) {
            ZkTestHelper.expireSession(zkClient);
            long newSessionId = zkClient.getSessionId();
            Assert.assertTrue(newSessionId != lastSessionId, "New session id should not equal to expired session id.");
