    Assert.assertEquals(Long.toHexString(stat.getEphemeralOwner()), expectedSessionId, "Ephemeral node is created by an unexpected session");
    // Delete the node to clean up, otherwise, the ephemeral node would be existed until the session
    // of its owner expires.
    _zkClient.delete(path);
}

